9|namespace Spectre.Console
10|{
11|    /// <summary>
12|    /// Represents a prompt.
13|    /// </summary>
14|    /// <typeparam name="T">The prompt result type.</typeparam>
15|    public sealed class TextPrompt<T> : IPrompt<T>
16|    {
17|        private readonly string _prompt;
18|        private readonly StringComparer? _comparer;
19|
20|        /// <summary>
21|        /// Gets or sets the prompt style.
22|        /// </summary>
23|        public Style? PromptStyle { get; set; }
24|
25|        /// <summary>
26|        /// Gets the list of choices.
27|        /// </summary>
28|        public List<T> Choices { get; } = new List<T>();
29|
30|        /// <summary>
31|        /// Gets or sets the message for invalid choices.
32|        /// </summary>
33|        public string InvalidChoiceMessage { get; set; } = "[red]Please select one of the available options[/]";
34|
35|        /// <summary>
36|        /// Gets or sets a value indicating whether input should
37|        /// be hidden in the console.
38|        /// </summary>
39|        public bool IsSecret { get; set; }
40|
41|        /// <summary>
42|        /// Gets or sets the validation error message.
43|        /// </summary>
44|        public string ValidationErrorMessage { get; set; } = "[red]Invalid input[/]";
45|
46|        /// <summary>
47|        /// Gets or sets a value indicating whether or not
48|        /// choices should be shown.
49|        /// </summary>
50|        public bool ShowChoices { get; set; } = true;
51|
52|        /// <summary>
53|        /// Gets or sets a value indicating whether or not
54|        /// default values should be shown.
55|        /// </summary>
56|        public bool ShowDefaultValue { get; set; } = true;
57|
58|        /// <summary>
59|        /// Gets or sets a value indicating whether or not an empty result is valid.
60|        /// </summary>
61|        public bool AllowEmpty { get; set; }
62|
63|        /// <summary>
64|        /// Gets or sets the converter to get the display string for a choice. By default
65|        /// the corresponding <see cref="TypeConverter"/> is used.
66|        /// </summary>
67|        public Func<T, string>? Converter { get; set; } = TypeConverterHelper.ConvertToString;
68|
69|        /// <summary>
70|        /// Gets or sets the validator.
71|        /// </summary>
72|        public Func<T, ValidationResult>? Validator { get; set; }
73|
74|        /// <summary>
75|        /// Gets or sets the default value.
76|        /// </summary>
77|        internal DefaultPromptValue<T>? DefaultValue { get; set; }
78|
79|        /// <summary>
80|        /// Initializes a new instance of the <see cref="TextPrompt{T}"/> class.
81|        /// </summary>
82|        /// <param name="prompt">The prompt markup text.</param>
83|        /// <param name="comparer">The comparer used for choices.</param>
84|        public TextPrompt(string prompt, StringComparer? comparer = null)
85|        {
86|            _prompt = prompt;
87|            _comparer = comparer;
88|        }
89|
90|        /// <summary>
91|        /// Shows the prompt and requests input from the user.
92|        /// </summary>
93|        /// <param name="console">The console to show the prompt in.</param>
94|        /// <returns>The user input converted to the expected type.</returns>
95|        /// <inheritdoc/>
96|        public T Show(IAnsiConsole console)
97|        {
98|            if (console is null)
99|            {
100|                throw new ArgumentNullException(nameof(console));
101|            }
102|
103|            return console.RunExclusive(() =>
104|            {
105|                var promptStyle = PromptStyle ?? Style.Plain;
106|                var converter = Converter ?? TypeConverterHelper.ConvertToString;
107|                var choices = Choices.Select(choice => converter(choice)).ToList();
108|                var choiceMap = Choices.ToDictionary(choice => converter(choice), choice => choice, _comparer);
109|
110|                WritePrompt(console);
111|
112|                while (true)
113|                {
114|                    var input = console.ReadLine(promptStyle, IsSecret, choices);
115|
116|                    // Nothing entered?
117|                    if (string.IsNullOrWhiteSpace(input))
118|                    {
119|                        if (DefaultValue != null)
120|                        {
121|                            console.Write(IsSecret ? "******" : converter(DefaultValue.Value), promptStyle);
122|                            console.WriteLine();
123|                            return DefaultValue.Value;
124|                        }
125|
126|                        if (!AllowEmpty)
127|                        {
128|                            continue;
129|                        }
130|                    }
131|
132|                    console.WriteLine();
133|
134|                    T? result;
135|                    if (Choices.Count > 0)
136|                    {
137|                        if (choiceMap.TryGetValue(input, out result) && result != null)
138|                        {
139|                            return result;
140|                        }
141|                        else
142|                        {
143|                            console.MarkupLine(InvalidChoiceMessage);
144|                            WritePrompt(console);
145|                            continue;
146|                        }
147|                    }
148|                    else if (!TypeConverterHelper.TryConvertFromString<T>(input, out result) || result == null)
149|                    {
150|                        console.MarkupLine(ValidationErrorMessage);
151|                        WritePrompt(console);
152|                        continue;
153|                    }
154|
155|                    // Run all validators
156|                    if (!ValidateResult(result, out var validationMessage))
157|                    {
158|                        console.MarkupLine(validationMessage);
159|                        WritePrompt(console);
160|                        continue;
161|                    }
162|
163|                    return result;
164|                }
165|            });
166|        }
167|
168|        /// <summary>
169|        /// Writes the prompt to the console.
170|        /// </summary>
171|        /// <param name="console">The console to write the prompt to.</param>
172|        private void WritePrompt(IAnsiConsole console)
173|        {
174|            if (console is null)
175|            {
176|                throw new ArgumentNullException(nameof(console));
177|            }
178|
179|            var builder = new StringBuilder();
180|            builder.Append(_prompt.TrimEnd());
181|
182|            if (ShowChoices && Choices.Count > 0)
183|            {
184|                var converter = Converter ?? TypeConverterHelper.ConvertToString;
185|                var choices = string.Join("/", Choices.Select(choice => converter(choice)));
186|                builder.AppendFormat(CultureInfo.InvariantCulture, " [blue][[{0}]][/]", choices);
187|            }
188|
189|            if (ShowDefaultValue && DefaultValue != null)
190|            {
191|                var converter = Converter ?? TypeConverterHelper.ConvertToString;
192|                builder.AppendFormat(
193|                    CultureInfo.InvariantCulture,
194|                    " [green]({0})[/]",
195|                    IsSecret ? "******" : converter(DefaultValue.Value));
196|            }
197|
198|            var markup = builder.ToString().Trim();
199|            if (!markup.EndsWith("?", StringComparison.OrdinalIgnoreCase) &&
200|                !markup.EndsWith(":", StringComparison.OrdinalIgnoreCase))
201|            {
202|                markup += ":";
203|            }
204|
205|            console.Markup(markup + " ");
206|        }
207|
208|        private bool ValidateResult(T value, [NotNullWhen(false)] out string? message)
209|        {
210|            if (Validator != null)
211|            {
212|                var result = Validator(value);
213|                if (!result.Successful)
214|                {
215|                    message = result.Message ?? ValidationErrorMessage;
216|                    return false;
217|                }
218|            }
219|
220|            message = null;
221|            return true;
222|        }
223|    }
