35|                {
36|                    return text;
37|                }
38|
39|                if (key.Key == ConsoleKey.Tab && autocomplete.Count > 0)
40|                {
41|                    var replace = AutoComplete(autocomplete, text);
42|                    if (!string.IsNullOrEmpty(replace))
43|                    {
44|                        // Render the suggestion
45|                        console.Write("\b \b".Repeat(text.Length), style);
46|                        console.Write(replace);
47|                        text = replace;
48|                        continue;
49|                    }
50|                }
51|
